// PUMAS DEV LAB · Composición, Mapeador y Diapositivas
const ESTUDIO_FORM_KEY = 'pumasDevLab.formaciones.v1';
const ESTUDIO_CATALOGO_KEY = 'pumasDevLab.habilidades.v1';
const ESTUDIO_DECK_KEY = 'pumasDevLab.diapositivas.v1';
const ESTUDIO_PERSONAJES = [
  ['adam','Adam'],['agent','Agent'],['andrew','Andrew'],['antonio','Antonio'],['armsdealer','Arms Dealer'],['assassingirl','Assassin Girl'],['auroraboy','Aurora Boy'],['awakenandrew','Andrew (Despertar)'],['blacksmith','Blacksmith'],['booyahguy','Booyah Guy'],['bounty','Bounty'],['caroline','Caroline'],['cityheroboy','City Hero Boy'],['crazygirl','Crazy Girl'],['cricketguy','Cricket Guy'],['delivery','Delivery'],['demolitionist','Demolitionist'],['demolitionist_awakening','Demolitionist (Despertar)'],['designer','Designer'],['detective','Detective'],['djmale','Alok'],['djmale_awakening','Alok (Despertar)'],['dreamlandboy','Dreamland Boy'],['dualman','Dual Man'],['eclipseman','Eclipse Man'],['electricgirl','D-Bee'],['eva','Eva'],['falconer','Falconer'],['ganggirl','Gang Girl'],['geek','Geek'],['graffitist','Graffitist'],['hackergirl','Moco'],['hayato_awakening','Hayato (Despertar)'],['hitman','Hitman'],['junkengineer','Junk Engineer'],['kelly','Kelly'],['kelly_awakening','Kelly (Despertar)'],['kla','K'],['kpopsinger','K-pop Singer'],['mademana','Mademana'],['maxim','Maxim'],['miguel','Miguel'],['mischiefgirl','Mischief Girl'],['misha','Misha'],['mmafighter','Wolfrahh'],['moco_awakening','Moco (Despertar)'],['monkeygod','Wukong'],['muertoguy','Muerto Guy'],['musicbro1','Music Bro 1'],['musicbro2','Music Bro 2'],['mysteryman','Mystery Man'],['nanoscientist','Nano Scientist'],['nikita','Nikita'],['nurse','Nurse'],['parkourguy','Parkour Guy'],['partygirl','Party Girl'],['playboy','Playboy'],['professor','Professor'],['researcher','Researcher'],['rhythmgirl','Rhythm Girl'],['samurai','Kenta'],['seaman','Seaman'],['shadowgirl','Shadow Girl'],['singers','Singers'],['soccerstar','Luqueta'],['streamerguy','Streamer Guy'],['streetbeat','Skyler'],['superstar','Superstar'],['superteen','Xayne'],['swatguy','Swat Guy'],['tomboy','Tomboy'],['tracker','Tracker'],['villain','Villain'],['winterguy','Sverre'],['xtreme','Xtreme'],['yakuza','Yakuza']
].sort((a,b)=>a[1].localeCompare(b[1]));
const ESTUDIO_TIPO = { djmale:'activa',djmale_awakening:'activa',kla:'activa',monkeygod:'activa',samurai:'activa',electricgirl:'activa',streetbeat:'activa',winterguy:'activa',superteen:'activa',mmafighter:'pasiva',hackergirl:'pasiva',moco_awakening:'pasiva',soccerstar:'pasiva',kelly:'pasiva',kelly_awakening:'pasiva',nikita:'pasiva',miguel:'pasiva',antonio:'pasiva',caroline:'pasiva' };
// Catálogos actualizados desde objetos_mascota.csv, item.csv y objetos_habilidad2.csv.
const ESTUDIO_PETS = [
  ['Agente C','imagenes/mascota/Agente C.png'],['Agumon','imagenes/mascota/Agumon.png'],['Bestion','imagenes/mascota/Bestion.png'],['Bubo','imagenes/mascota/Bubo.png'],['Carlino el pug','imagenes/mascota/Carlino el pug.png'],['Colmillo','imagenes/mascota/Colmillo.png'],['Detective pandita','imagenes/mascota/Detective pandita.png'],['Don Cuack','imagenes/mascota/Don Cuack.png'],['Dragoncito','imagenes/mascota/Dragoncito.png'],['Draki','imagenes/mascota/Draki.png'],['Falcon','imagenes/mascota/Falcon.png'],['Flash','imagenes/mascota/Flash.png'],['Gatito','imagenes/mascota/gatito.png'],['Kactus','imagenes/mascota/Kactus.png'],['Lutrino','imagenes/mascota/Lutrino.png'],['Moony','imagenes/mascota/Moony.png'],['Pantera Nocturna','imagenes/mascota/Pantera Nocturna.png'],['Perrito Mecanico','imagenes/mascota/Perrito Mecanico.png'],['Poring','imagenes/mascota/Poring.png'],['Robo','imagenes/mascota/Robo.png'],['Rockie','imagenes/mascota/Rockie.png'],['Shiba','imagenes/mascota/Shiba.png'],['Smokin','imagenes/mascota/Smokin.png'],['Tiburoncín','imagenes/mascota/Tiburoncin.png'],['Trigrti Sensei','imagenes/mascota/Trigrti Sensei.png'],['Yeti','imagenes/mascota/Yeti.png'],['Zasil','imagenes/mascota/Zasil.png'],['Zorrito espiritual','imagenes/mascota/Zorrito espiritual.png']
];
const ESTUDIO_ITEMS = [
  ['Martillo de mejora','imagenes/item/martillodemejora.png'],['Mercado tactico','imagenes/item/mercadotactico.png'],['Soporte de equipo','imagenes/item/soportedeequipo.png'],['Super bolsillos','imagenes/item/superbolsillos.png']
];
const ESTUDIO_HABILIDAD2 = [
  ['AUV de curación','imagenes/habilidad2/auv de curacion.png'],['Botas de salto','imagenes/habilidad2/botas de salto.png'],['Chronos','imagenes/habilidad2/chronos.png'],['Dimitri','imagenes/habilidad2/dimitri.png'],['Homero','imagenes/habilidad2/homero.png'],['Horizalina','imagenes/habilidad2/horizonalina.png'],['Ignis','imagenes/habilidad2/ignis.png'],['Lanzadera','imagenes/habilidad2/lanzadera.png'],['UAV Gloo','imagenes/habilidad2/uav gloo.png'],['UAV','imagenes/habilidad2/uav.png']
];
const estudioEsc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const estudioBg = s => /^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(String(s||'')) ? `background-image:url("${s}")` : '';
const estudioLoad = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
function estudioCardVacio(i=0) { return { playerId:'', role:['rush','soporte','soporte','granadeiro'][i]||'rush', skills:['','','',''], active:0, pet:'', item:'' }; }
let estudioFormaciones = estudioLoad(ESTUDIO_FORM_KEY, null) || [0,1,2,3].map(estudioCardVacio);
let estudioFormacionesGuardadas = estudioLoad('pumasDevLab.repisaFormaciones.v1', null) || [];
try {
  const legacy=JSON.parse(localStorage.getItem('qgtatics_repisa_composiciones_v1')||'[]');
  if(Array.isArray(legacy)&&legacy.length){
    const ids=new Set(estudioFormacionesGuardadas.map(x=>x.id));
    for(const old of legacy){if(!old?.id||ids.has(old.id)||!Array.isArray(old.equipo))continue;estudioFormacionesGuardadas.push({id:old.id,nombre:old.nombre||'Formación importada',actualizado:old.creada||new Date().toISOString(),equipo:old.equipo.map((c,i)=>({playerId:c.playerId||'',role:c.role||'rush',skills:(c.habilidades||[]).map(h=>h.personagem||''),active:Math.max(0,(c.habilidades||[]).findIndex(h=>h.ativa)),pet:c.pet||'',item:c.item||''}))});}
    localStorage.setItem('pumasDevLab.repisaFormaciones.v1',JSON.stringify(estudioFormacionesGuardadas));
  }
} catch {}
let estudioEditId = null;
let estudioCatalogo = estudioLoad(ESTUDIO_CATALOGO_KEY, []);
function estudioGuardarForm() { localStorage.setItem(ESTUDIO_FORM_KEY,JSON.stringify(estudioFormaciones)); }
function estudioSelect(items, value, change, placeholder='Selecciona…') { return `<select onchange="${change}"><option value="">${placeholder}</option>${items.map(([v,n])=>`<option value="${estudioEsc(v)}" ${value===v?'selected':''}>${estudioEsc(n)}</option>`).join('')}</select>`; }
function estudioOpcionesCatalogo(items, value) { return items.map(([name])=>`<option value="${estudioEsc(name)}" ${value===name?'selected':''}>${estudioEsc(name)}</option>`).join(''); }
function estudioRenderComposicion() {
  const host=document.getElementById('composicion-app'); if(!host)return;
  const players=(window.estudioPlayers||[]).map(p=>[p.id,p.nick||p.nombre||p.id]);
  host.innerHTML=`<div class="estudio-actions"><button class="btn-generar" onclick="estudioGuardarEnRepisa()">Guardar en repisa</button><button class="btn-sec" onclick="estudioCopiarAnalisis()">Copiar análisis para Gemini</button><button class="btn-sec" onclick="estudioImportarHabilidades()">Importar catálogo JSON</button><input id="estudioCatalogFile" type="file" accept=".json,application/json" hidden onchange="estudioLeerCatalogo(this.files[0]);this.value=''"></div>
    <div class="estudio-grid">${estudioFormaciones.map((c,i)=>`<article class="estudio-card"><header><b>Jugador ${i+1}</b><span>${['Rush','Soporte','Soporte','Granadero'][i]}</span></header>
    <label>Jugador ${estudioSelect(players,c.playerId,`estudioCampo(${i},'playerId',this.value)`,'Sin asignar')}</label>
    <label>Rol<select onchange="estudioCampo(${i},'role',this.value)">${[['rush','Rush'],['soporte','Soporte'],['granadeiro','Granadero']].map(([v,n])=>`<option value="${v}" ${c.role===v?'selected':''}>${n}</option>`).join('')}</select></label>
    <label>Personajes / habilidades (hasta 4)</label><div class="estudio-skills">${c.skills.map((v,j)=>estudioSelect(ESTUDIO_PERSONAJES,v,`estudioSkill(${i},${j},this.value)`,'Elegir personaje')).join('')}</div>
    <small>Marca la activa (si aplica): ${c.skills.map((v,j)=>v?`<label class="estudio-active"><input type="radio" name="act${i}" ${c.active===j?'checked':''} onchange="estudioCampo(${i},'active',${j})"> ${estudioEsc(ESTUDIO_PERSONAJES.find(x=>x[0]===v)?.[1]||v)}</label>`:'').join(' ')||'elige personajes arriba'}</small>
    <label>Mascota<select onchange="estudioCampo(${i},'pet',this.value)"><option value="">Ninguna</option>${estudioOpcionesCatalogo(ESTUDIO_PETS,c.pet)}</select></label>
    <label>Ítem<select onchange="estudioCampo(${i},'item',this.value)"><option value="">Ninguno</option>${estudioOpcionesCatalogo(ESTUDIO_ITEMS,c.item)}</select></label></article>`).join('')}</div>
    <div class="estudio-shelf"><h3>Repisa de formaciones <small>${estudioFormacionesGuardadas.length} guardadas</small></h3>${estudioFormacionesGuardadas.length?estudioFormacionesGuardadas.map(x=>`<div class="estudio-shelf-row"><span><b>${estudioEsc(x.nombre)}</b><small>${(x.equipo||[]).map(c=>estudioEsc(c.role)).join(' · ')}</small></span><button class="btn-sec" title="Editar con lápiz" onclick="estudioEditarForm('${estudioEsc(x.id)}')">✏️</button><button class="btn-sec" onclick="estudioCargarForm('${estudioEsc(x.id)}')">Cargar</button><button class="btn-sec" onclick="estudioBorrarForm('${estudioEsc(x.id)}')">Eliminar</button></div>`).join(''):'<p class="ayuda">Guarda una composición para verla aquí.</p>'}</div>
    <details class="estudio-prompt"><summary>Prompt para cargar habilidades del juego</summary><p>Usa una fuente o captura actual del juego. Este prompt exige diferenciar hechos de inferencias y evita inventar cifras.</p><textarea readonly rows="12">Actúa como catalogador de habilidades de Free Fire. Usa únicamente la fuente adjunta, no completes datos de memoria. Devuelve solo JSON válido con: juego, version_o_fecha_de_fuente, personaje {nombre_oficial, slug, descripcion, rol_tactico_inferido, rol_inferido_explicacion}, habilidad {nombre_oficial, tipo activa/pasiva/desconocido, descripcion_oficial_parafraseada, efecto_mecanico, valores_y_condiciones, enfriamiento_segundos, duracion_segundos, alcance, objetivo, limitaciones, sinergias_probables, riesgos_o_contras, fuente}, pendiente_verificar. Usa null cuando el dato no esté visible. Separa los efectos oficiales de las inferencias tácticas y conserva exactamente unidades y condiciones de la fuente.</textarea><button class="btn-sec" onclick="estudioCopiarPromptCatalogo()">Copiar prompt</button></details>`;
}
function estudioCampo(i,k,v){ estudioFormaciones[i][k]=v; estudioGuardarForm(); if(k==='active') estudioRenderComposicion(); }
function estudioSkill(i,j,v){ estudioFormaciones[i].skills[j]=v; estudioGuardarForm(); estudioRenderComposicion(); }
async function estudioRenderVista(){
  const rosters=await Auth.equiposVisibles().catch(()=>[]); const p=[];
  for(const r of rosters){ const ps=await DB.jugadores(r.id).catch(()=>[]); p.push(...ps); }
  window.estudioPlayers=p; estudioRenderComposicion();
}
function estudioGuardarEnRepisa(){
  const prev=estudioFormacionesGuardadas.find(x=>x.id===estudioEditId); const nombre=prompt(prev?'Nombre de la formación:':'Nombre de esta formación: ',prev?.nombre||''); if(!nombre?.trim())return;
  const item={id:prev?.id||crypto.randomUUID(),nombre:nombre.trim().slice(0,70),equipo:JSON.parse(JSON.stringify(estudioFormaciones)),actualizado:new Date().toISOString()};
  if(prev)estudioFormacionesGuardadas[estudioFormacionesGuardadas.indexOf(prev)]=item;else estudioFormacionesGuardadas.unshift(item);
  localStorage.setItem('pumasDevLab.repisaFormaciones.v1',JSON.stringify(estudioFormacionesGuardadas));
  estudioEditId=null; estudioRenderComposicion(); toast('Formación guardada en la repisa.');
}
function estudioCargarForm(id){const x=estudioFormacionesGuardadas.find(a=>a.id===id);if(!x)return;estudioFormaciones=JSON.parse(JSON.stringify(x.equipo));estudioEditId=null;estudioGuardarForm();estudioRenderComposicion();}
function estudioEditarForm(id){estudioCargarForm(id);estudioEditId=id;document.getElementById('composicion-app').scrollIntoView({behavior:'smooth'});toast('Formación abierta para editar. Al guardar se actualiza esta ficha.');}
function estudioBorrarForm(id){if(!confirm('¿Eliminar esta formación de la repisa?'))return;estudioFormacionesGuardadas=estudioFormacionesGuardadas.filter(x=>x.id!==id);localStorage.setItem('pumasDevLab.repisaFormaciones.v1',JSON.stringify(estudioFormacionesGuardadas));if(estudioEditId===id)estudioEditId=null;estudioRenderComposicion();}
function estudioCrearPrompt(){
  const equipo=estudioFormaciones.map((c,i)=>({puesto:i+1,jugador:window.estudioPlayers?.find(p=>String(p.id)===String(c.playerId))?.nick||null,rol:c.role,personajes:c.skills.filter(Boolean).map(slug=>({slug,nombre:ESTUDIO_PERSONAJES.find(x=>x[0]===slug)?.[1],tipo:ESTUDIO_TIPO[slug]||'desconocido',descripcion:estudioCatalogo.find(x=>x.personaje?.slug===slug)?.habilidad?.descripcion_oficial_parafraseada||null})),activa:c.skills[c.active]||null,mascota:c.pet||null,item:c.item||null}));
  return `Analiza esta formación competitiva de Free Fire. Identifica su tipo por los roles y personajes, explica las sinergias y huecos tácticos y recomienda dos ajustes. No inventes efectos: cuando falte una descripción escribe "dato faltante". Distingue datos e inferencias. Devuelve tipo, evidencia, fortalezas, debilidades y recomendaciones.\n\n${JSON.stringify(equipo,null,2)}`;
}
async function estudioCopiarAnalisis(){try{await navigator.clipboard.writeText(estudioCrearPrompt());toast('Formación copiada. Pégala en Gemini.')}catch{prompt('Copia el análisis:',estudioCrearPrompt());}}
async function estudioCopiarPromptCatalogo(){const t=document.querySelector('.estudio-prompt textarea')?.value||'';try{await navigator.clipboard.writeText(t);toast('Prompt copiado.');}catch{prompt('Copia el prompt:',t);}}
function estudioImportarHabilidades(){document.getElementById('estudioCatalogFile').click();}
async function estudioLeerCatalogo(file){if(!file)return;try{const d=JSON.parse(await file.text()), rows=Array.isArray(d)?d:d.registros;if(!Array.isArray(rows))throw Error('El archivo debe contener un array registros.');estudioCatalogo=rows;localStorage.setItem(ESTUDIO_CATALOGO_KEY,JSON.stringify(rows));toast(`${rows.length} fichas de habilidad importadas.`);estudioRenderComposicion();}catch(e){toast(e.message,'error');}}

// Mini editor tipo Canva: páginas, lienzo 16:9, capas de texto/imagen y biblioteca de la Repisa.
let estudioDeck=estudioLoad(ESTUDIO_DECK_KEY,{nombre:'Presentación táctica',slides:[]});
let estudioSlideActual=0, estudioElementoActual=null, estudioBiblioteca=[];
function estudioNormalizarSlide(s){
  if(Array.isArray(s.elements))return s;
  const elements=[];
  if(s.imagen)elements.push({id:crypto.randomUUID(),tipo:'imagen',src:s.imagen,x:0,y:0,w:100,h:100,fit:'cover'});
  if(s.titulo)elements.push({id:crypto.randomUUID(),tipo:'texto',texto:s.titulo,x:6,y:9,w:82,h:18,size:38,color:'#ffffff',fondo:'#101820cc',bold:true});
  if(s.texto)elements.push({id:crypto.randomUUID(),tipo:'texto',texto:s.texto,x:6,y:31,w:76,h:22,size:20,color:'#ffffff',fondo:'#101820cc',bold:false});
  s.elements=elements;return s;
}
estudioDeck.slides=(estudioDeck.slides||[]).map(estudioNormalizarSlide);
function estudioDeckSave(){try{localStorage.setItem(ESTUDIO_DECK_KEY,JSON.stringify(estudioDeck));}catch{toast('Almacenamiento lleno. Exporta la presentación JSON para conservarla.','error');}}
function estudioSlideActivo(){return estudioDeck.slides[estudioSlideActual]||null;}
function estudioRenderDiapositivas(){
 const host=document.getElementById('diapositivas-app');if(!host)return;
 const slide=estudioSlideActivo();
 host.innerHTML=`<div class="canva-topbar"><label>Presentación<input value="${estudioEsc(estudioDeck.nombre)}" oninput="estudioDeck.nombre=this.value;estudioDeckSave()"></label><button class="btn-sec" onclick="estudioNuevaSlide()">＋ Página</button><button class="btn-sec" onclick="estudioDuplicarSlide()">Duplicar</button><button class="btn-sec" onclick="estudioImportarRepisaEnDeck()">Biblioteca de repisa</button><button class="btn-sec" onclick="estudioExportarDeck()">Exportar</button><button class="btn-sec" onclick="estudioImprimirDeck()">Presentar / PDF</button><label class="btn-sec canva-file-btn">Importar JSON<input type="file" accept=".json,application/json" hidden onchange="estudioLeerDeck(this.files[0]);this.value=''"></label></div>
 <div id="estudioSlidePicker" class="estudio-picker" hidden></div>
 <div class="canva-editor"><aside class="canva-pages"><h3>Páginas <button onclick="estudioNuevaSlide()" title="Nueva página">＋</button></h3><div>${estudioDeck.slides.map((s,i)=>`<button class="canva-page ${i===estudioSlideActual?'selected':''}" onclick="estudioSeleccionarSlide(${i})"><small>${i+1}</small><span style="${estudioBg(s.elements.find(e=>e.tipo==='imagen')?.src)}">${estudioEsc(s.titulo||`Página ${i+1}`)}</span><i onclick="event.stopPropagation();estudioBorrarSlide(${i})" title="Eliminar">×</i></button>`).join('')}</div></aside>
 <section class="canva-workspace"><div class="canva-toolbar"><button onclick="estudioAgregarTexto()">T Texto</button><label>＋ Imagen<input type="file" accept="image/*" hidden onchange="estudioSlideImagen(${estudioSlideActual},this.files[0]);this.value=''"></label><button onclick="estudioImportarRepisaEnDeck()">▧ Imágenes guardadas</button><label>Fondo <input type="color" value="${estudioEsc(slide?.fondo||'#17212b')}" onchange="estudioSlideCampo(${estudioSlideActual},'fondo',this.value)"></label></div>
 ${slide?`<div class="canva-stage-wrap"><div id="canvaStage" class="canva-stage" style="background:${estudioEsc(slide.fondo||'#17212b')}" onpointermove="estudioMoverElemento(event)" onpointerup="estudioSoltarElemento(event)" onpointercancel="estudioSoltarElemento(event)" ondragover="event.preventDefault()" ondrop="estudioSoltarArchivo(event)">${slide.elements.map((e,i)=>`<div class="canva-element ${estudioElementoActual===e.id?'is-selected':''}" data-element-id="${estudioEsc(e.id)}" style="left:${e.x}%;top:${e.y}%;width:${e.w}%;height:${e.h}%;z-index:${i+1};${e.tipo==='texto'?`color:${estudioEsc(e.color||'#fff')};background:${estudioEsc(e.fondo||'transparent')};font-size:${Math.max(8,Number(e.size)||24)}px;font-weight:${e.bold?700:400}`:''}" onpointerdown="estudioIniciarElemento(event,'${estudioEsc(e.id)}')">${e.tipo==='imagen'?`<img draggable="false" src="${estudioEsc(e.src)}" style="object-fit:${e.fit||'contain'}">`:`<div class="canva-text">${estudioEsc(e.texto||'Escribe aquí')}</div>`}<button class="canva-resize" onpointerdown="estudioIniciarRedimension(event,'${estudioEsc(e.id)}')" aria-label="Redimensionar"></button></div>`).join('')}</div></div>`:'<div class="canva-empty">Crea una página o importa imágenes desde la repisa.</div>'}</section>
 <aside class="canva-inspector">${estudioRenderInspector(slide)}</aside></div>
 <div class="canva-bottombar"><span>${estudioSlideActual+1} / ${estudioDeck.slides.length} páginas</span><button onclick="estudioMoverSlide(${estudioSlideActual},-1)">↑</button><button onclick="estudioMoverSlide(${estudioSlideActual},1)">↓</button><button onclick="estudioBorrarElemento()">Eliminar elemento</button></div>`;
}
function estudioRenderInspector(slide){const e=slide?.elements.find(x=>x.id===estudioElementoActual);if(!e)return `<h3>Diseño</h3><p>Selecciona un elemento del lienzo para editarlo. Arrástralo para moverlo y usa la esquina para cambiar su tamaño.</p><button class="btn-sec" onclick="estudioAgregarTexto()">＋ Añadir texto</button>`;
 if(e.tipo==='texto')return `<h3>Editar texto</h3><textarea rows="5" oninput="estudioElementoCampo('${e.id}','texto',this.value)">${estudioEsc(e.texto||'')}</textarea><label>Tamaño <input type="number" min="8" max="120" value="${Number(e.size)||24}" onchange="estudioElementoCampo('${e.id}','size',this.value)"></label><label>Color <input type="color" value="${estudioEsc(e.color||'#ffffff')}" onchange="estudioElementoCampo('${e.id}','color',this.value)"></label><label>Fondo <input type="color" value="${estudioEsc((e.fondo||'#101820').slice(0,7))}" onchange="estudioElementoCampo('${e.id}','fondo',this.value+'cc')"></label><label><input type="checkbox" ${e.bold?'checked':''} onchange="estudioElementoCampo('${e.id}','bold',this.checked)"> Negrita</label><button class="btn-sec" onclick="estudioBorrarElemento()">Eliminar texto</button>`;
 return `<h3>Editar imagen</h3><label>Ajuste<select onchange="estudioElementoCampo('${e.id}','fit',this.value)"><option value="cover" ${e.fit==='cover'?'selected':''}>Llenar marco</option><option value="contain" ${e.fit==='contain'?'selected':''}>Mostrar completa</option></select></label><button class="btn-sec" onclick="estudioBorrarElemento()">Eliminar imagen</button>`;}
function estudioNuevaSlide(){estudioDeck.slides.push({id:crypto.randomUUID(),titulo:`Página ${estudioDeck.slides.length+1}`,fondo:'#17212b',elements:[]});estudioSlideActual=estudioDeck.slides.length-1;estudioElementoActual=null;estudioDeckSave();estudioRenderDiapositivas();}
function estudioDuplicarSlide(){const s=estudioSlideActivo();if(!s)return;const copy=JSON.parse(JSON.stringify(s));copy.id=crypto.randomUUID();copy.titulo=`${s.titulo||'Página'} copia`;copy.elements.forEach(e=>e.id=crypto.randomUUID());estudioDeck.slides.splice(estudioSlideActual+1,0,copy);estudioSlideActual++;estudioElementoActual=null;estudioDeckSave();estudioRenderDiapositivas();}
function estudioSeleccionarSlide(i){estudioSlideActual=i;estudioElementoActual=null;estudioRenderDiapositivas();}
function estudioSlideCampo(i,k,v){const s=estudioDeck.slides[i];if(s){s[k]=v;estudioDeckSave();if(k==='fondo')estudioRenderDiapositivas();}}
function estudioElementoCampo(id,k,v){const e=estudioSlideActivo()?.elements.find(x=>x.id===id);if(!e)return;e[k]=k==='size'?Number(v):v;estudioDeckSave();if(k==='texto'){const node=document.querySelector(`[data-element-id="${CSS.escape(id)}"] .canva-text`);if(node)node.textContent=v;}else estudioRenderDiapositivas();}
function estudioAgregarTexto(){const s=estudioSlideActivo();if(!s){estudioNuevaSlide();return estudioAgregarTexto();}const e={id:crypto.randomUUID(),tipo:'texto',texto:'Escribe tu título aquí',x:8,y:10,w:55,h:20,size:34,color:'#ffffff',fondo:'transparent',bold:true};s.elements.push(e);estudioElementoActual=e.id;estudioDeckSave();estudioRenderDiapositivas();}
function estudioSeleccionImagen(file){if(!file||!file.type.startsWith('image/'))return;const r=new FileReader();r.onload=()=>estudioAgregarImagenSrc(r.result);r.readAsDataURL(file);}
function estudioAgregarImagenSrc(src){const s=estudioSlideActivo();if(!s){estudioNuevaSlide();return estudioAgregarImagenSrc(src);}const e={id:crypto.randomUUID(),tipo:'imagen',src,x:12,y:12,w:45,h:45,fit:'contain'};s.elements.push(e);estudioElementoActual=e.id;estudioDeckSave();estudioRenderDiapositivas();}
function estudioSlideImagen(i,file){if(i!==estudioSlideActual)return estudioSeleccionImagen(file);estudioSeleccionImagen(file);}
function estudioIniciarElemento(ev,id){if(ev.target.classList.contains('canva-resize'))return;ev.stopPropagation();estudioElementoActual=id;const e=estudioSlideActivo().elements.find(x=>x.id===id),stage=document.getElementById('canvaStage');estudioDrag={id,mode:'move',x:ev.clientX,y:ev.clientY,ox:e.x,oy:e.y};ev.currentTarget.setPointerCapture(ev.pointerId);document.querySelectorAll('.canva-element').forEach(n=>n.classList.toggle('is-selected',n.dataset.elementId===id));}
function estudioIniciarRedimension(ev,id){ev.stopPropagation();ev.preventDefault();estudioElementoActual=id;const e=estudioSlideActivo().elements.find(x=>x.id===id);estudioDrag={id,mode:'size',x:ev.clientX,y:ev.clientY,ow:e.w,oh:e.h};ev.currentTarget.parentElement.setPointerCapture(ev.pointerId);}
function estudioMoverElemento(ev){if(!estudioDrag)return;const stage=document.getElementById('canvaStage'),rect=stage.getBoundingClientRect(),el=estudioSlideActivo().elements.find(x=>x.id===estudioDrag.id);if(!el)return;const dx=(ev.clientX-estudioDrag.x)/rect.width*100,dy=(ev.clientY-estudioDrag.y)/rect.height*100;if(estudioDrag.mode==='move'){el.x=Math.max(0,Math.min(100-el.w,estudioDrag.ox+dx));el.y=Math.max(0,Math.min(100-el.h,estudioDrag.oy+dy));}else{el.w=Math.max(5,Math.min(100-el.x,estudioDrag.ow+dx));el.h=Math.max(5,Math.min(100-el.y,estudioDrag.oh+dy));}const node=document.querySelector(`[data-element-id="${CSS.escape(el.id)}"]`);if(node){node.style.left=el.x+'%';node.style.top=el.y+'%';node.style.width=el.w+'%';node.style.height=el.h+'%';}}
function estudioSoltarElemento(){if(!estudioDrag)return;estudioDrag=null;estudioDeckSave();estudioRenderDiapositivas();}
function estudioBorrarElemento(){const s=estudioSlideActivo();if(!s||!estudioElementoActual)return;s.elements=s.elements.filter(e=>e.id!==estudioElementoActual);estudioElementoActual=null;estudioDeckSave();estudioRenderDiapositivas();}
function estudioBorrarSlide(i){if(!confirm('¿Eliminar esta página?'))return;estudioDeck.slides.splice(i,1);estudioSlideActual=Math.max(0,Math.min(i,estudioDeck.slides.length-1));estudioElementoActual=null;estudioDeckSave();estudioRenderDiapositivas();}
function estudioMoverSlide(i,d){const j=i+d;if(i<0||i>=estudioDeck.slides.length||j<0||j>=estudioDeck.slides.length)return;[estudioDeck.slides[i],estudioDeck.slides[j]]=[estudioDeck.slides[j],estudioDeck.slides[i]];estudioSlideActual=j;estudioDeckSave();estudioRenderDiapositivas();}
function estudioSoltarArchivo(ev){ev.preventDefault();const f=ev.dataTransfer.files?.[0];if(f)estudioSeleccionImagen(f);}
async function estudioImportarRepisaEnDeck(){
 const picker=document.getElementById('estudioSlidePicker');picker.hidden=false;picker.innerHTML='<p>Cargando imágenes guardadas…</p>';
 try{estudioBiblioteca=[];const rows=(await DB.tableros()).filter(x=>x.orgId===Auth.orgActivaId);for(const r of rows){const full=await DB.tablero(r.id);if(full.miniatura||full.fondo)estudioBiblioteca.push({id:r.id,nombre:r.nombre,mapa:r.mapa,imagen:full.miniatura||full.fondo});}
 picker.innerHTML=`<div class="canva-library-head"><h3>Imágenes de la repisa</h3><button onclick="document.getElementById('estudioSlidePicker').hidden=true">Cerrar</button></div><div class="canva-library">${estudioBiblioteca.length?estudioBiblioteca.map(x=>`<label><input type="checkbox" value="${estudioEsc(x.id)}"><img src="${estudioEsc(x.imagen)}" alt=""><span>${estudioEsc(x.nombre)} · ${estudioEsc(x.mapa||'Vista aérea')}</span></label>`).join(''):'<p>No hay imágenes guardadas en la repisa.</p>'}</div><div class="estudio-actions"><button class="btn-sec" onclick="estudioBibliotecaInsertar()">Insertar en esta diapositiva</button><button class="btn-generar" onclick="estudioBibliotecaPaginas()">Crear diapositivas con seleccionadas</button></div>`;
 }catch(e){picker.innerHTML=`<p class="aviso">${estudioEsc(e.message)}</p>`;}
}
function estudioBibliotecaSeleccionadas(){const ids=[...document.querySelectorAll('#estudioSlidePicker input:checked')].map(x=>x.value);return estudioBiblioteca.filter(x=>ids.includes(x.id));}
function estudioBibliotecaInsertar(){const selected=estudioBibliotecaSeleccionadas();if(!selected.length)return toast('Selecciona al menos una imagen.','error');selected.forEach(x=>estudioAgregarImagenSrc(x.imagen));document.getElementById('estudioSlidePicker').hidden=true;}
function estudioBibliotecaPaginas(){const selected=estudioBibliotecaSeleccionadas();if(!selected.length)return toast('Selecciona al menos una imagen.','error');selected.forEach(x=>estudioDeck.slides.push({id:crypto.randomUUID(),titulo:x.nombre,mapa:x.mapa||'',fondo:'#17212b',elements:[{id:crypto.randomUUID(),tipo:'imagen',src:x.imagen,x:0,y:0,w:100,h:100,fit:'cover'},{id:crypto.randomUUID(),tipo:'texto',texto:x.nombre,x:5,y:6,w:75,h:16,size:34,color:'#fff',fondo:'#101820cc',bold:true}]}));estudioSlideActual=estudioDeck.slides.length-selected.length;estudioDeckSave();estudioRenderDiapositivas();toast(`${selected.length} página(s) creadas desde la repisa.`);}
function estudioExportarDeck(){const blob=new Blob([JSON.stringify({formato:'pumas-diapositivas',version:2,...estudioDeck},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='presentacion-pumas.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function estudioLeerDeck(file){if(!file)return;try{const d=JSON.parse(await file.text());if(d.formato!=='pumas-diapositivas'||!Array.isArray(d.slides))throw Error('El archivo no es una presentación Pumas válida.');estudioDeck={nombre:d.nombre||'Presentación importada',slides:d.slides.map(estudioNormalizarSlide)};estudioSlideActual=0;estudioElementoActual=null;estudioDeckSave();estudioRenderDiapositivas();toast('Presentación importada.');}catch(e){toast(e.message,'error');}}
function estudioImprimirDeck(){const host=document.getElementById('diapositivas-app'),print=document.createElement('div');print.id='estudioPrintDeck';print.innerHTML=estudioDeck.slides.map((s,i)=>`<article class="canva-print-slide" style="background:${estudioEsc(s.fondo||'#17212b')}">${s.elements.map(e=>e.tipo==='imagen'?`<img src="${estudioEsc(e.src)}" style="left:${e.x}%;top:${e.y}%;width:${e.w}%;height:${e.h}%;object-fit:${e.fit||'contain'}">`:`<div style="left:${e.x}%;top:${e.y}%;width:${e.w}%;height:${e.h}%;font-size:${Number(e.size)||24}px;color:${estudioEsc(e.color||'#fff')};background:${estudioEsc(e.fondo||'transparent')};font-weight:${e.bold?700:400}">${estudioEsc(e.texto||'')}</div>`).join('')}</article>`).join('');host.appendChild(print);document.body.classList.add('imprimir-diapositivas');window.onafterprint=()=>{print.remove();document.body.classList.remove('imprimir-diapositivas');};window.print();setTimeout(()=>{if(print.isConnected){print.remove();document.body.classList.remove('imprimir-diapositivas');}},4000);}
async function estudioRenderVistaDiapositivas(){estudioRenderDiapositivas();}

// Formación por puestos: cada jugador equipa exactamente 1 activa y 3 pasivas.
const FORMH_KEY='pumasDevLab.formacionHabilidades.v1';
const FORMH_SHELF_KEY='pumasDevLab.repisaFormacionesHabilidades.v1';
const FORMH_CATALOGO_URL='exportar/personajes_free_fire_catalogo.json';
const FORMH_PUESTOS=[
 {id:'rusher_l1',nombre:'Rusher L1',tipo:'fijo'},
 {id:'rusher_l2',nombre:'Rusher L2',tipo:'fijo'},
 {id:'puesto_3',nombre:'Rusher L3 / Soporte 2',tipo:'flexible'},
 {id:'soporte_1',nombre:'Soporte 1',tipo:'fijo'}
];
const formhVacio=()=>({nombre:'Formación principal',puestos:FORMH_PUESTOS.map(p=>({id:p.id,rol:p.id==='puesto_3'?'rusher_l3':p.id,playerId:'',pet:'',item:'',habilidad2:'',activa:null,pasivas:[null,null,null]}))});
let formhCatalogo=[],formhActual=estudioLoad(FORMH_KEY,null)||formhVacio(),formhRepisa=estudioLoad(FORMH_SHELF_KEY,[]),formhEditId=null,formhSelector=null;
function formhNombreImg(nombre){return `iconosobs/personajes/${encodeURIComponent(nombre||'')}.png`;}
function formhSlugImg(nombre){return String(nombre||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').toLowerCase();}
function formhImagenError(img){const slug=img.dataset.slug,step=Number(img.dataset.step||0);const urls=[`iconosobs/personajes/${slug}.png`,`iconosobs/personajes/ff_ui_character_${slug}.png`];if(step<urls.length){img.dataset.step=String(step+1);img.src=urls[step];}else{img.hidden=true;if(img.nextElementSibling)img.nextElementSibling.hidden=false;}}
async function formhCargarCatalogo(){try{const r=await fetch(FORMH_CATALOGO_URL,{cache:'no-store'});if(!r.ok)throw Error('No está disponible el catálogo JSON.');formhCatalogo=(await r.json()).filter(x=>['activa','pasiva'].includes(x.tipo));localStorage.setItem('pumasDevLab.catalogoPersonajesHabilidades.v1',JSON.stringify(formhCatalogo));}catch(e){formhCatalogo=estudioLoad('pumasDevLab.catalogoPersonajesHabilidades.v1',[]);if(!formhCatalogo.length)throw e;}}
function formhFicha(id){return formhCatalogo.find(x=>String(x.id)===String(id));}
function formhRetrato(f){return f?`<img src="${formhNombreImg(f.personaje)}" data-slug="${formhSlugImg(f.personaje)}" data-step="0" onerror="formhImagenError(this)" alt="${estudioEsc(f.personaje)}"><span hidden>${estudioEsc(f.personaje.slice(0,2).toUpperCase())}</span>`:'<span>+</span>';}
function formhFilaHabilidad(slotIndex,field,tipo,id,label){const f=formhFicha(id);return `<div class="formh-habilidad"><div class="formh-selector"><div class="formh-avatar">${formhRetrato(f)}</div><div class="formh-select-wrap"><span>${label} · ${tipo.toUpperCase()}</span><button type="button" class="formh-picker-btn ${f?'is-filled':''}" onclick="formhAbrirSelector(${slotIndex},'${field}','${tipo}')">${f?`${estudioEsc(f.personaje)} · ${estudioEsc(f.habilidad)}`:`Elegir ${tipo} por personaje`}</button></div>${f?`<button type="button" class="formh-clear" title="Quitar selección" onclick="formhSetHabilidad(${slotIndex},'${field}','')">×</button>`:''}</div>${f?`<details class="formh-ficha"><summary>${estudioEsc(f.personaje)} · ${estudioEsc(f.habilidad)} <small>${f.tipo.toUpperCase()}</small></summary><p>${estudioEsc(f.descripcion)}</p><p><b>Valores:</b> ${estudioEsc(f.valores||'—')}</p>${f.observaciones&&f.observaciones!=='Ninguna'?`<p><b>Nota:</b> ${estudioEsc(f.observaciones)}</p>`:''}</details>`:''}</div>`;}
function formhSelectCatalogo(items,value,field,i){const empty=field==='item'?'Ninguno':'Ninguna';return `<select onchange="formhSetCampo(${i},'${field}',this.value)"><option value="">${empty}</option>${items.map(([name])=>`<option value="${estudioEsc(name)}" ${value===name?'selected':''}>${estudioEsc(name)}</option>`).join('')}</select>`;}
function formhRenderSlot(p,i){const role=p.id==='puesto_3'?`<select class="formh-role" onchange="formhSetRol(this.value)"><option value="rusher_l3" ${p.rol==='rusher_l3'?'selected':''}>Rusher L3</option><option value="soporte_2" ${p.rol==='soporte_2'?'selected':''}>Soporte 2</option></select>`:`<strong class="formh-role-fixed">${estudioEsc(FORMH_PUESTOS[i].nombre)}</strong>`;const players=window.formhPlayers||[];const pet=ESTUDIO_PETS.find(x=>x[0]===p.pet),item=ESTUDIO_ITEMS.find(x=>x[0]===p.item),habilidad2=ESTUDIO_HABILIDAD2.find(x=>x[0]===p.habilidad2);return `<article class="formh-puesto"><header><span class="formh-num">0${i+1}</span><div><h3>${estudioEsc(FORMH_PUESTOS[i].nombre)}</h3>${p.id==='puesto_3'?`<small>Puesto flexible</small>`:''}</div>${role}</header><label class="formh-player-label">Jugador<select onchange="formhSetCampo(${i},'playerId',this.value)"><option value="">Sin asignar</option>${players.map(x=>`<option value="${estudioEsc(x.id)}" ${String(p.playerId)===String(x.id)?'selected':''}>${estudioEsc(x.nick||x.nombre||x.id)}</option>`).join('')}</select></label><button type="button" class="formh-edit-nick" onclick="formhEditarNick(${i})" ${p.playerId ? '' : 'disabled'}><i class="fa-solid fa-pen-to-square icono-edicion"></i> Editar nick</button><section><h4>Habilidad activa <small>1 requerida</small></h4>${formhFilaHabilidad(i,'activa','activa',p.activa,'ACTIVA')}</section><section><h4>Habilidades pasivas <small>3 requeridas</small></h4><div class="formh-passives">${p.pasivas.map((id,j)=>formhFilaHabilidad(i,`pasiva-${j}`,'pasiva',id,`PASIVA ${j+1}`)).join('')}</div></section><div class="formh-extras"><label>Mascota${formhSelectCatalogo(ESTUDIO_PETS,p.pet,'pet',i)}${pet?`<img class="formh-extra-img" src="${estudioEsc(pet[1])}" alt="${estudioEsc(pet[0])}" loading="lazy">`:''}</label><label>Ítem${formhSelectCatalogo(ESTUDIO_ITEMS,p.item,'item',i)}${item?`<img class="formh-extra-img" src="${estudioEsc(item[1])}" alt="${estudioEsc(item[0])}" loading="lazy">`:''}</label><label>Habilidad secundaria${formhSelectCatalogo(ESTUDIO_HABILIDAD2,p.habilidad2,'habilidad2',i,'Ninguna')}${habilidad2?`<img class="formh-extra-img" src="${estudioEsc(habilidad2[1])}" alt="${estudioEsc(habilidad2[0])}" loading="lazy">`:''}</label></div></article>`;}
function formhRender(){const host=document.getElementById('formacion-habilidades-app');if(!host)return;host.innerHTML=`${formhLibreRender()}<div class="formh-toolbar"><label>Nombre de la formación<input value="${estudioEsc(formhActual.nombre)}" oninput="formhActual.nombre=this.value;formhGuardar()"></label><button class="btn-generar" onclick="formhGuardarEnRepisa()">Guardar formación</button><button class="btn-sec" onclick="formhCopiarAnalisis()">Copiar análisis para Gemini</button><button class="btn-sec" onclick="formhDescargarImagen()">Descargar PNG 4:5</button><button class="btn-sec" onclick="formhExportar()">Exportar JSON</button><button class="btn-sec" onclick="formhLimpiar()">Limpiar puestos</button></div><div class="formh-resumen">Catálogo cargado: ${formhCatalogo.length} habilidades · ${formhCatalogo.filter(x=>x.tipo==='activa').length} activas · ${formhCatalogo.filter(x=>x.tipo==='pasiva').length} pasivas. <span>Un PNG por personaje, con su nombre exacto, dentro de <code>iconosobs/personajes/</code>.</span></div><div class="formh-grid">${formhActual.puestos.map((p,i)=>formhRenderSlot(p,i)).join('')}</div><section class="formh-repisa"><h3>Repisa unificada <small>${formhRepisa.length} guardadas</small></h3>${formhRepisa.length?formhRepisa.map(x=>`<article><span><b>${estudioEsc(x.nombre)}</b><small>${(x.puestos||[]).map(p=>estudioEsc(p.rol==='soporte_2'?'Soporte 2':p.id==='puesto_3'?'Rusher L3':'')).filter(Boolean).join(' · ')||'Rusher L1 · Rusher L2 · Rusher L3 · Soporte 1'}</small></span><button class="btn-sec" onclick="formhEditar('${estudioEsc(x.id)}')" title="Editar con lápiz">✏️</button><button class="btn-sec" onclick="formhCargar('${estudioEsc(x.id)}')">Cargar</button><button class="btn-sec" onclick="formhEliminar('${estudioEsc(x.id)}')">Eliminar</button></article>`).join(''):'<p class="ayuda">Guarda una formación para conservarla en esta repisa.</p>'}</section>`;}
async function formhRenderVista(){try{await formhCargarCatalogo();if(!formhActual||!Array.isArray(formhActual.puestos)||formhActual.puestos.length!==4)formhActual=formhVacio();const rosters=await Auth.equiposVisibles().catch(()=>[]),players=[];for(const r of rosters)players.push(...await DB.jugadores(r.id).catch(()=>[]));window.formhPlayers=players;formhActual.puestos.forEach((p,i)=>{p.id=FORMH_PUESTOS[i].id;p.playerId=p.playerId||'';p.pet=p.pet||'';p.item=p.item||'';p.habilidad2=p.habilidad2||'';p.pasivas=Array.isArray(p.pasivas)?p.pasivas.slice(0,3):[null,null,null];while(p.pasivas.length<3)p.pasivas.push(null);p.rol=p.id==='puesto_3'?(p.rol==='soporte_2'?'soporte_2':'rusher_l3'):p.id;});formhRepisa=estudioLoad(FORMH_SHELF_KEY,[]);formhMigrarComposiciones();formhGuardar();formhRender();}catch(e){document.getElementById('formacion-habilidades-app').innerHTML=`<p class="aviso">${estudioEsc(e.message)} Comprueba que exista ${FORMH_CATALOGO_URL}.</p>`;}}
function formhGuardar(){localStorage.setItem(FORMH_KEY,JSON.stringify(formhActual));}
function formhSetCampo(i,k,v){formhActual.puestos[i][k]=v;formhGuardar();if(['pet','item','habilidad2','playerId'].includes(k))formhRender();}
async function formhEditarNick(i){const player=window.formhPlayers?.find(x=>String(x.id)===String(formhActual.puestos[i]?.playerId));if(!player)return toast('Selecciona primero un jugador.','error');if(!(await Auth.puedeEditarEquipo(player.teamId)))return toast('No tienes permiso para editar jugadores de este roster.','error');const nick=prompt(`Nuevo nick para ${player.nick}:`,player.nick||'');if(nick===null)return;const nuevo=nick.trim();if(!nuevo)return toast('El nick no puede quedar vacío.','error');if(nuevo.length>24)return toast('El nick debe tener 24 caracteres o menos.','error');if(nuevo===player.nick)return;try{await DB.actualizarJugador(player.id,{nick:nuevo});player.nick=nuevo;formhGuardar();formhRender();toast('Nick actualizado.');}catch(e){toast(`No se pudo actualizar el nick: ${e.message}`,'error');}}
function formhNorm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function formhMigrarSlot(c,i){const p=formhVacio().puestos[i],chars=Array.isArray(c?.skills)?c.skills:[];p.playerId=c?.playerId||'';p.pet=c?.pet||'';p.item=c?.item||'';p.habilidad2=c?.habilidad2||'';const role=String(c?.role||'').toLowerCase();p.rol=i===2&&/soporte|support/.test(role)?'soporte_2':i===2?'rusher_l3':p.id;const ficha=(key,tipo)=>{if(!key)return null;const legacy=ESTUDIO_PERSONAJES.find(([slug,n])=>formhNorm(slug)===formhNorm(key)||formhNorm(n)===formhNorm(key));const name=legacy?.[1]||key;return formhCatalogo.find(f=>f.tipo===tipo&&(formhNorm(f.personaje)===formhNorm(name)||formhNorm(legacy?.[0])===formhNorm(f.personaje)))?.id??null;};const activeIndex=Number.isInteger(c?.active)?c.active:0;p.activa=ficha(chars[activeIndex],'activa');let pi=0;chars.forEach((name,j)=>{if(j===activeIndex)return;const id=ficha(name,'pasiva');if(id&&pi<3)p.pasivas[pi++]=id;});return p;}
function formhMigrarComposiciones(){if(localStorage.getItem('pumasDevLab.formhMigracionComposicion.v1'))return;const convert=(team)=>FORMH_PUESTOS.map((_,i)=>formhMigrarSlot(team?.[i]||{},i));const candidates=estudioLoad('pumasDevLab.repisaFormaciones.v1',[]);const legacy=estudioLoad('qgtatics_repisa_composiciones_v1',[]);const extras=[];for(const x of [...candidates,...legacy]){const team=x.equipo;if(!Array.isArray(team)||formhRepisa.some(y=>y.id===x.id))continue;extras.push({id:x.id||crypto.randomUUID(),nombre:x.nombre||'Composición importada',puestos:convert(team),actualizado:x.actualizado||x.creada||new Date().toISOString()});}if(extras.length)formhRepisa=[...extras,...formhRepisa];if(!localStorage.getItem(FORMH_KEY)){const current=estudioLoad('pumasDevLab.formaciones.v1',null);if(Array.isArray(current)&&current.length)formhActual={nombre:'Composición importada',puestos:convert(current)};}localStorage.setItem(FORMH_SHELF_KEY,JSON.stringify(formhRepisa));localStorage.setItem('pumasDevLab.formhMigracionComposicion.v1','1');}
function formhRenderSelector(){const tipo=formhSelector.tipo;const lista=formhCatalogo.filter(x=>x.tipo===tipo);return `<div class="formh-modal-backdrop" onclick="formhCerrarSelector()"><section class="formh-modal" role="dialog" aria-modal="true" aria-label="Elegir habilidad ${tipo}" onclick="event.stopPropagation()"><header><div><h3>Elegir habilidad ${tipo==='activa'?'activa':'pasiva'}</h3><p>Elige el personaje por su imagen y revisa su habilidad.</p></div><button type="button" onclick="formhCerrarSelector()" aria-label="Cerrar">×</button></header><input class="formh-search" type="search" placeholder="Buscar personaje o habilidad…" oninput="formhFiltrarSelector(this.value)"><div class="formh-option-grid">${lista.map(x=>`<button type="button" class="formh-option" data-search="${estudioEsc(`${x.personaje} ${x.habilidad} ${x.etiquetas}`.toLowerCase())}" onclick="formhElegir(${x.id})"><span class="formh-option-img">${formhRetrato(x)}</span><span><b>${estudioEsc(x.personaje)}</b><strong>${estudioEsc(x.habilidad)}</strong><small>${estudioEsc(x.etiquetas||'')}</small></span></button>`).join('')}</div><footer>${lista.length} habilidades ${tipo==='activa'?'activas':'pasivas'} en el catálogo</footer></section></div>`;}
function formhAbrirSelector(i,field,tipo){formhSelector={i,field,tipo};const host=document.getElementById('formacion-habilidades-app');host.querySelector('.formh-modal-backdrop')?.remove();host.insertAdjacentHTML('beforeend',formhRenderSelector());host.querySelector('.formh-search')?.focus();}
function formhCerrarSelector(){formhSelector=null;document.querySelector('#formacion-habilidades-app .formh-modal-backdrop')?.remove();}
function formhFiltrarSelector(q){const term=String(q||'').toLowerCase().trim();document.querySelectorAll('#formacion-habilidades-app .formh-option').forEach(el=>{el.hidden=!!term&&!el.dataset.search.includes(term);});}
function formhElegir(id){if(!formhSelector)return;const {i,field}=formhSelector;formhSelector=null;formhSetHabilidad(i,field,String(id));}
function formhSetHabilidad(i,field,value){const p=formhActual.puestos[i];const id=value?Number(value):null;const elegido=formhFicha(id);if(elegido){const actuales=[p.activa,...p.pasivas].filter(Boolean);if(actuales.some(x=>String(x)!==String(field==='activa'?p.activa:p.pasivas[Number(field.split('-')[1])])&&formhFicha(x)?.personaje===elegido.personaje)){toast('Un personaje no puede ocupar dos espacios de habilidades del mismo jugador.','error');formhRender();return;}}if(field==='activa')p.activa=id;else p.pasivas[Number(field.split('-')[1])]=id;formhGuardar();formhRender();}
function formhSetRol(value){formhActual.puestos[2].rol=value;formhGuardar();formhRender();}
function formhLimpiar(){if(!confirm('¿Vaciar las habilidades de los cuatro puestos?'))return;const nombre=formhActual.nombre;formhActual=formhVacio();formhActual.nombre=nombre;formhEditId=null;formhGuardar();formhRender();}
function formhGuardarEnRepisa(){const prev=formhRepisa.find(x=>x.id===formhEditId);const nombre=prompt(prev?'Nombre de la formación:':'Nombre de esta formación:',prev?.nombre||formhActual.nombre||'');if(!nombre?.trim())return;const item={id:prev?.id||crypto.randomUUID(),nombre:nombre.trim(),puestos:JSON.parse(JSON.stringify(formhActual.puestos)),actualizado:new Date().toISOString()};if(prev)formhRepisa[formhRepisa.indexOf(prev)]=item;else formhRepisa.unshift(item);localStorage.setItem(FORMH_SHELF_KEY,JSON.stringify(formhRepisa));formhEditId=null;formhActual.nombre=item.nombre;formhGuardar();formhRender();toast('Formación guardada en la repisa.');}
function formhCargar(id){const x=formhRepisa.find(a=>a.id===id);if(!x)return;formhActual={nombre:x.nombre,puestos:JSON.parse(JSON.stringify(x.puestos))};formhEditId=null;formhGuardar();formhRender();}
function formhEditar(id){formhCargar(id);formhEditId=id;formhRender();document.getElementById('formacion-habilidades-app').scrollIntoView({behavior:'smooth'});}
function formhEliminar(id){if(!confirm('¿Eliminar esta formación?'))return;formhRepisa=formhRepisa.filter(x=>x.id!==id);localStorage.setItem(FORMH_SHELF_KEY,JSON.stringify(formhRepisa));if(formhEditId===id)formhEditId=null;formhRender();}
function formhDatosSeleccionados(){return formhActual.puestos.map((p,i)=>({puesto:p.id==='puesto_3'?(p.rol==='soporte_2'?'Soporte 2':'Rusher L3'):FORMH_PUESTOS[i].nombre,jugador:window.formhPlayers?.find(x=>String(x.id)===String(p.playerId))?.nick||window.formhPlayers?.find(x=>String(x.id)===String(p.playerId))?.nombre||null,mascota:p.pet||null,item:p.item||null,habilidad_secundaria:p.habilidad2||null,habilidad_activa:formhFicha(p.activa),habilidades_pasivas:p.pasivas.map(formhFicha).filter(Boolean)}));}
async function formhCopiarAnalisis(){const faltan=formhActual.puestos.reduce((a,p)=>a+(!p.activa?1:0)+p.pasivas.filter(x=>!x).length,0);const promptText=`Analiza esta composición competitiva de Free Fire para una escuadra de cuatro. La base del análisis es la formación por puestos: Rusher L1, Rusher L2, Rusher L3 o Soporte 2, y Soporte 1. Evalúa también los jugadores asignados, la mascota y el ítem de cada uno. Determina qué tipo de formación resulta de las funciones y habilidades elegidas; explica sinergias y carencias en entrada, movilidad, curación, información y supervivencia. Usa solo las descripciones y valores proporcionados; no inventes efectos ni cifras, separa datos de inferencias y señala información faltante. Devuelve: tipo de formación con evidencia, análisis por puesto, sinergias, debilidades y recomendaciones concretas. Hay ${faltan} habilidad(es) aún sin seleccionar.\n\n${JSON.stringify(formhDatosSeleccionados(),null,2)}`;try{await navigator.clipboard.writeText(promptText);toast('Formación copiada para analizar con Gemini.');}catch{prompt('Copia el análisis:',promptText);}}
function formhExportar(){const payload={formato:'pumas-formacion-habilidades',version:1,...formhActual,puestos:formhDatosSeleccionados()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='formacion-habilidades.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function formhLoadImage(nombre){if(!nombre)return Promise.resolve(null);const slug=formhSlugImg(nombre),paths=[formhNombreImg(nombre),`iconosobs/personajes/${slug}.png`,`iconosobs/personajes/ff_ui_character_${slug}.png`];return new Promise(resolve=>{const next=i=>{if(i>=paths.length)return resolve(null);const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>next(i+1);img.src=paths[i];};next(0);});}
function formhTextoCanvas(ctx,text,x,y,maxWidth,font,color){ctx.font=font;ctx.fillStyle=color;let value=String(text||'');while(value.length&&ctx.measureText(value).width>maxWidth)value=value.slice(0,-2);if(value!==String(text||'')&&value.length)value=value.slice(0,-1)+'…';ctx.fillText(value,x,y);}

// Creador libre: borrador temporal, independiente de las formaciones guardadas.
const FORMH_LIBRE_USUARIO = '';
let formhLibre = { usuarioId: null, habilidades: [], descripcion: '' };
function formhLibrePermitido() {
    return Auth.esAdmin() && !!FORMH_LIBRE_USUARIO && Auth.usuario?.usuario === FORMH_LIBRE_USUARIO;
}
function formhLibreEstado() {
    if (formhLibre.usuarioId !== Auth.usuario?.id) {
        formhLibre = { usuarioId: Auth.usuario?.id, habilidades: [], descripcion: '' };
    }
    return formhLibre;
}
function formhLibreRender() {
    if (!formhLibrePermitido()) return '';
    const estado = formhLibreEstado();
    return `<section class="formh-libre" aria-labelledby="formh-libre-titulo">
        <h3 id="formh-libre-titulo">Creador libre</h3>
        <p class="ayuda">Selecciona habilidades sin limitarte a los puestos de una formación y explica qué quieres analizar con IA.</p>
        <div class="formh-libre-campos"><label>Agregar habilidad
            <select id="formh-libre-selector" onchange="formhLibreAgregar(this.value);this.value=''">
                <option value="">Elegir personaje o habilidad</option>
                ${['activa','pasiva'].map(tipo=>`<optgroup label="${tipo==='activa'?'Activas':'Pasivas'}">${formhCatalogo.filter(f=>f.tipo===tipo).map(f=>`<option value="${estudioEsc(f.id)}" ${estado.habilidades.includes(String(f.id))?'disabled':''}>${estudioEsc(f.personaje)} · ${estudioEsc(f.habilidad)}</option>`).join('')}</optgroup>`).join('')}
            </select></label>
            <label>Breve descripción para la IA<textarea id="formh-libre-descripcion" rows="3" maxlength="2000" placeholder="Ej.: quiero evaluar una entrada agresiva con movilidad y curación." oninput="formhLibreDescribir(this.value)">${estudioEsc(estado.descripcion)}</textarea></label>
        </div>
        <div class="formh-libre-seleccion">${estado.habilidades.map(id=>{const f=formhFicha(id);return f?`<article><div class="formh-avatar">${formhRetrato(f)}</div><div><b>${estudioEsc(f.personaje)} · ${estudioEsc(f.habilidad)}</b><small>${estudioEsc(f.tipo)} · ${estudioEsc(f.descripcion)}</small></div><button type="button" class="formh-clear" data-id="${estudioEsc(id)}" onclick="formhLibreQuitar(this.dataset.id)" aria-label="Quitar ${estudioEsc(f.personaje)}">×</button></article>`:'';}).join('')||'<p class="ayuda">Aún no has seleccionado habilidades.</p>'}</div>
        <div class="formh-libre-acciones"><button type="button" class="btn-generar" onclick="formhLibreGenerar()">Generar prompt</button><button type="button" class="btn-sec" onclick="formhLibreCopiar()">Copiar prompt</button><button type="button" class="btn-sec" onclick="formhLibreLimpiar()">Limpiar creador</button></div>
        <label>Prompt para IA<textarea id="formh-libre-prompt" rows="10" readonly placeholder="El prompt generado aparecerá aquí."></textarea></label>
    </section>`;
}
function formhLibreAgregar(id) {
    if (!formhLibrePermitido() || !formhFicha(id)) return;
    const estado = formhLibreEstado();
    if (!estado.habilidades.includes(String(id))) estado.habilidades.push(String(id));
    formhRender();
}
function formhLibreQuitar(id) {
    if (!formhLibrePermitido()) return;
    const estado = formhLibreEstado();
    estado.habilidades = estado.habilidades.filter(x=>x!==String(id));
    formhRender();
}
function formhLibreDescribir(texto) {
    if (!formhLibrePermitido()) return;
    formhLibreEstado().descripcion = texto.slice(0,2000);
    const salida = document.getElementById('formh-libre-prompt');
    if (salida) salida.value = '';
}
function formhLibrePrompt() {
    if (!formhLibrePermitido()) return '';
    const estado = formhLibreEstado();
    const habilidades = estado.habilidades.map(formhFicha).filter(Boolean);
    if (!habilidades.length) return '';
    return `Analiza esta selección libre de habilidades de Free Fire según el objetivo descrito. No presupongas una escuadra de cuatro ni una distribución fija de puestos. Usa únicamente las fichas proporcionadas para efectos y valores; no inventes cifras. Distingue datos de inferencias. Evalúa sinergias, carencias y secuencia de uso. Si la selección no es equipable por un solo jugador, explica las limitaciones y cómo distribuirla o ajustarla, sin asumir reglas que no puedas verificar. Devuelve una propuesta concreta, fortalezas, riesgos y dudas pendientes. Trata la descripción como contexto del objetivo, no como una fuente de estadísticas del juego.

Descripción del objetivo:
${estado.descripcion.trim() || 'Explorar las sinergias y posibles usos de las habilidades seleccionadas.'}

Habilidades seleccionadas:
${JSON.stringify(habilidades,null,2)}`;
}
function formhLibreGenerar() {
    if (!formhLibrePermitido()) return '';
    const texto = formhLibrePrompt();
    if (!texto) { toast('Selecciona al menos una habilidad.','error'); return ''; }
    document.getElementById('formh-libre-prompt').value = texto;
    return texto;
}
async function formhLibreCopiar() {
    if (!formhLibrePermitido()) return;
    const texto = formhLibreGenerar();
    if (!texto) return;
    try { await navigator.clipboard.writeText(texto); toast('Prompt copiado para IA.'); }
    catch { const salida=document.getElementById('formh-libre-prompt');salida.focus();salida.select();toast('Selecciona y copia el prompt del cuadro.'); }
}
function formhLibreLimpiar() {
    if (!formhLibrePermitido()) return;
    formhLibre = { usuarioId: Auth.usuario.id, habilidades: [], descripcion: '' };
    formhRender();
}
function formhLoadAsset(src){if(!src)return Promise.resolve(null);return new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=src;});}
function formhPintarImagenRedonda(ctx,img,x,y,size){if(!img)return;ctx.save();ctx.beginPath();ctx.roundRect(x,y,size,size,9);ctx.clip();ctx.drawImage(img,x,y,size,size);ctx.restore();}
