  ctx.fillStyle='#0d2532';ctx.fillRect(0,0,W,194);ctx.fillStyle='#16d9e5';ctx.fillRect(48,42,5,80);
  ctx.font='700 16px Arial';ctx.fillStyle='#45e5ec';ctx.fillText('PUMAS GAMING  /  FREE FIRE',70,57);
  formhTextoCanvas(ctx,formhActual.nombre||'Formación del equipo',70,111,850,'700 38px Arial','#f3f8fb');
  ctx.font='13px Arial';ctx.fillStyle='#91a8b5';ctx.fillText('PLANTILLA TÁCTICA  ·  4 PUESTOS  ·  HABILIDADES Y EQUIPAMIENTO',70,145);
  ctx.textAlign='right';ctx.font='12px Arial';ctx.fillStyle='#91a8b5';ctx.fillText(new Date().toLocaleDateString('es-CO'),1030,57);ctx.textAlign='left';
  const cards=formhActual.puestos.map((p,i)=>{const player=window.formhPlayers?.find(a=>String(a.id)===String(p.playerId));const pet=ESTUDIO_PETS.find(x=>x[0]===p.pet),item=ESTUDIO_ITEMS.find(x=>x[0]===p.item),extra=ESTUDIO_HABILIDAD2.find(x=>x[0]===p.habilidad2);const role=p.id==='puesto_3'?(p.rol==='soporte_2'?'Soporte 2':'Rusher L3'):FORMH_PUESTOS[i].nombre;return {p,i,playerName:player?.nick||player?.nombre||'Jugador sin asignar',role,pet,item,extra};});
