    skills.forEach(([label,f],j)=>{const sy=y+54+j*43;ctx.beginPath();ctx.roundRect(x+22,sy,590,36,8);ctx.fillStyle=j===0?'#133440':'#14232e';ctx.fill();const img=charImgs[i*4+j];if(img)formhPintarImagenRedonda(ctx,img,x+27,sy+3,30);else{ctx.fillStyle='#2a4755';ctx.beginPath();ctx.roundRect(x+27,sy+3,30,30,7);ctx.fill();ctx.fillStyle='#7fd9df';ctx.font='700 10px Arial';ctx.fillText(f?.personaje?.slice(0,2).toUpperCase()||'—',x+34,sy+22);}
      ctx.font='700 9px Arial';ctx.fillStyle=j===0?'#50e4e9':'#83a0ad';ctx.fillText(label,x+68,sy+14);formhTextoCanvas(ctx,f?`${f.personaje} · ${f.habilidad}`:'Sin seleccionar',x+68,sy+29,526,'600 12px Arial',f?'#e6eef2':'#718691');});
    ctx.strokeStyle='#233a46';ctx.beginPath();ctx.moveTo(x+632,y+54);ctx.lineTo(x+632,y+h-18);ctx.stroke();
